insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Old Fitzgerald 7 Year","rar":"shelf","f":"Old Fitzgerald","x":"7 Year","p":100.0,"ay":7.0,"al":"7 yr","nas":false,"et":"standard","ms":"wheated","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Old Fitzgerald 7 Year Old","Old Fitzgerald 7-Year-Old"],"img":"https://heavenhilldistillery.com/images/old-fitz-7-spring-18.png","u":"https://heavenhilldistillery.com/old-fitzgerald-7-year-old.php","pr":"Heaven Hill","mk":"e041a023-e5dd-41c5-8a25-ef93d27831c0"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');update cellar.products set aliases = array_remove(aliases, 'Old Fitzgerald') where id = '94f0dbcf-9c07-40fe-a416-d214de7c20a7';
